argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-p7-activate.mjs'
try{[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log('{"error":"timeout"}');process.exit(0)},6500);
try{const v=await(await fetch('http://127.0.0.1:17447/json/version')).json();const w=new WebSocket(v.webSocketDebuggerUrl);
w.addEventListener('open',()=>w.send(JSON.stringify({id:1,method:'Target.activateTarget',params:{targetId:'D625D2F1944A0B6F8149A9EFDCEC522D'}})),{once:true});
w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify({activated:!!z.result,error:z.error?.message||null}));process.exit(0)}})
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,110)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
